package io.github.diodeme.ji.security.oauth;

import java.net.URI;

/** Binds an ephemeral loopback listener before an authorization URI is emitted. */
public interface LoopbackCallbackPort {
    CallbackBinding bind(String sessionId);

    interface CallbackBinding extends AutoCloseable {
        URI callbackUri();

        @Override
        void close();
    }
}
